const LAT_MAX = -23.45057;
const LON_MIN = -46.80902;
const K = 0.9162956026250916;
const ESCALA = 3353.565641196462;

/** lat/lng → ponto no viewBox. */
export function projetar(lat: number, lng: number): { x: number; y: number } {
  return { x: (lng - LON_MIN) * K * ESCALA, y: (LAT_MAX - lat) * ESCALA };
}

