/**
 * O ponto está na ÁREA ATENDIDA? Ray casting sobre os distritos mantidos.
 * É este teste que decide quem aparece no mapa e quem vira "fora de São Paulo"
 * no rodapé — errar aqui erra o número que a pessoa lê.
 */
export function dentroDaCidade(lat: number, lng: number): boolean {
  for (let d = 0; d < ANEIS.length; d++) {
    const [laMin, lnMin, laMax, lnMax] = CAIXAS[d];
    if (lat < laMin || lat > laMax || lng < lnMin || lng > lnMax) continue;
    const p = ANEIS[d];
    let dentro = false;
    for (let i = 0, j = p.length - 1; i < p.length; j = i++) {
      if ((p[i][0] > lat) !== (p[j][0] > lat)
          && lng < ((p[j][1] - p[i][1]) * (lat - p[i][0])) / (p[j][0] - p[i][0]) + p[i][1]) {
        dentro = !dentro;
      }
    }
    if (dentro) return true;
  }
  return false;
}
